@import 'deprecate';

/**
 * @summary Initializes Prompt style notification
 *
 * @name base
 * @selector .slds-modal_prompt
 * @restrict section[role="alertdialog"]
 * @support dev-ready
 * @variant
 */
.slds-modal_prompt,
.slds-modal--prompt {

  .slds-modal__header {
    border-bottom: 0;
  }

  .slds-modal__content {
    padding-left: $spacing-x-large;
    padding-right: $spacing-x-large;
  }

  .slds-modal__footer {
    border-top: 0;
    text-align: center;
  }
}
